from pathlib import Path
from PIL import Image
import html,json
p=Path(__file__).parent
E=lambda s:html.escape(s).replace('\n','<br>')
used=[]
def fig(src,caption,x,y,w,angle=0,maxh=None,light=False):
    iw,ih=Image.open(p/'raw'/f'{src}.png').size
    if maxh and (w-28)*ih/iw+63>maxh:w=28+(maxh-63)*iw/ih
    used.append(src)
    units=sum(1 if ord(c)>127 else .55 for c in caption)
    cap=min(21,max(15,(w-36)/max(1,units)))
    return f'<figure class="native checked {"light" if light else ""}" style="left:{x}px;top:{y}px;width:{w}px;--cap:{cap}px;transform:rotate({angle}deg)"><img src="../raw/{src}.png"><figcaption class="checked">{E(caption)}</figcaption></figure>'
def note(text,x,y,w=400,size=31,height=160,small=False):
    return f'<p class="note checked {"small" if small else ""}" style="left:{x}px;top:{y}px;width:{w}px;height:{height}px;font-size:{size}px">{E(text)}</p>'
items=[]
def add(name,title,sub,features,build):items.append(dict(name=name,title=title,sub=sub,features=features,build=build))

add('小红书封面','我的梦，给 TA 解。\nTA 的梦，换我闯。','秋秋机 · 梦境 × 解梦馆\n从醒来的一点残渣，到走进 TA 心里的那一场。','记梦与解梦 · 选择式闯梦 · 醒后联动',lambda:fig('dream-scene','推开门，梦就开始了。',110,580,640,-1.4)+fig('dream-options','这一幕，走哪一条？',165,1050,565,1.1)+fig('journal-reading-one','同一个梦，也想听 TA 怎么说。',795,630,325,2,maxh=695,light=True)+note('夜里，\n再靠近一点。',815,1230,275,34,150))
add('选人和编织','进谁的梦，\n也让谁来客串。','选一个做梦人，最多再带 2 个客串角色。\n递 0—3 个关键词；最近聊天也可选择带入，贴近当下。','做梦人 · 0—2 位客串 · 关键词与近况',lambda:fig('setup-people','01 / 做梦人和客串，自己挑。',120,550,875,-.8,maxh=450)+fig('setup-keywords','02 / 递三个关键词，也可以留空。',150,1030,600,.7,maxh=340)+fig('dream-setup-chat','03 / 最近聊天，开或关。',790,1060,325,-1,maxh=220)+note('客串怎么出现，\n会参考做梦人\n对他们的关系和感觉。',790,1310,320,23,120,True))
add('每幕选路','每一条选择，\n都把梦往别处带。','读这一幕，再从 3 个回应里选一个。\n两条顺着梦往下走，一条碰到 TA 抗拒的东西；界面不会标答案。','读幕文 · 亲自回应 · 记录你的选择',lambda:fig('dream-scene','01 / 先看 TA 的梦里发生了什么。',125,550,920,-.8)+fig('dream-options','02 / 这一步，由你选。',155,1120,690,.8,maxh=310)+fig('dream-chosen','选过的那句话，会留下。',895,1120,220,0,maxh=190)+note('接下来的一幕，\n沿着这次回应继续。',875,1320,230,23,110,True))
add('越熟越懂','像不像 TA，\n熟悉的人会认出来。','从 TA 的夜梦进入时，好感、印象与共同记忆会影响熟悉程度。\n越懂 TA，抗拒那条路越会在措辞里露出一点不对劲。','还生 · 熟了些 · 很懂 TA',lambda:fig('familiar-familiar0','01 / 还生：凭心选。',100,540,595,-.7,maxh=285)+fig('familiar-familiar1','02 / 熟了些：细读那处措辞。',150,850,595,.7,maxh=285)+fig('familiar-play','03 / 很懂 TA：认出不像 TA 的那条。',200,1160,595,-.5,maxh=285)+note('熟悉程度\n在入梦时确定。\n\n这一场里，\n档位不会中途变。',850,720,270,30,350))
add('梦先挣扎','碰到了逆鳞，\n还有一次回应。','梦先变质一幕，TA 的潜意识在护着那个东西。\n再选一次：一条回应能让 TA 直面，另外两条会让梦碎。','触碰抗拒 · 一幕挣扎 · 一次安抚机会',lambda:fig('dream-struggle-scene','01 / 梦还在，只是绷到了极限。',120,550,940,-.7)+fig('dream-struggle-options','02 / 这次，TA 真正需要哪种回应？',145,1125,900,.7,maxh=330))
add('抵达梦核','一直往深处走，\n终于看见梦围着谁。','顺着梦走到足够深，再做最后一步回应。\n抵达时会收束这一场，也会点明这场梦真正围着的那件事。','抵达 · 梦核 · 可带走的小物件',lambda:fig('dream-arrive','原结局：叙事、梦核和手里的东西。',160,545,635,-.7,maxh=900)+note('一路选过的回应，\n都还在幕文里。\n\n抵达之后，\n也能回到刚才\n那一幕再重选。',870,650,250,30,470))
add('直面那件事','你没有退开，\nTA 也没有逃。','挣扎那一幕回应对了，会走向“直面”。\n它会说清 TA 一直绕开的是什么，也可能落下一件梦里的东西。','第四种结局：直面 · 看见 TA 绕开的事',lambda:fig('dream-face','原结局：TA 一直绕开的，是这件事。',165,545,620,.7,maxh=900)+note('同一场梦，\n可以走到不同的\n收束方式。\n\n“直面”\n有自己的结局正文。',850,700,270,31,430))
add('梦碎之后','这条路没走通，\n也能知道为什么。','梦承受不住时，你会被惊醒、逐出梦境。\n结局会留下触碰的那一步，以及它为何在 TA 的梦里走不通。','梦碎 · 选择回显 · 为什么走不通',lambda:fig('dream-broken','梦碎的正文和原因，都留在这场梦里。',160,550,840,-.7,maxh=850)+note('想试另一条路，点结局下方“回到刚才的决策点重选”。',150,1430,900,24,60,True))
add('回档醒来与续梦','想重选，回一幕。\n想歇歇，就醒来。','已选过的回应能点“从这里重选”，之后的进展会被抹去。\n可以主动醒来，也能同时保留多场梦，回来继续或重进。','从这里重选 · 主动醒来 · 多场梦分别保留',lambda:fig('dream-chosen','01 / 这里可以回档。',120,550,830,-.7)+fig('dream-wake','02 / 主动醒来，也能回到最后的决策点。',155,790,835,.7)+fig('dream-saves','03 / 每一场，都留着自己的进度和结局。',185,1050,800,-.5,maxh=370))
add('把东西带出梦','醒来，手里\n还攥着一件东西。','抵达或直面的结局里，可以点“带出梦去”。\n它会进入购物里的“我的物品”，按从谁的梦里来分开收着。','带出梦去 → 我的物品 · 来源留在你这里',lambda:fig('keepsake-before','01 / 梦里落在手里的那件。',125,550,900,-.7)+fig('keepsake-after','02 / 点过以后：已经带出来了。',155,990,875,.7)+note('已经带出的东西，回档不会收回。',145,1410,920,27,60,True))
add('物品和聊天联动','你知道它的来处，\nTA 只觉得眼熟。','物品会影响一对一相处；TA 见了眼熟，说不上在哪里见过。\n14 天没提起会变浅，30 天回到梦里；聊天提到名字能续留。','物品 × 聊天 · 眼熟的秘密 · 会慢慢淡掉',lambda:fig('inventory-group','01 / 我的物品：单独一组，记着来源。',125,545,890,-.7,light=True)+fig('chat-keepsake-crop','02 / 聊天里的作用：TA 会觉得眼熟。',155,1030,850,.7,maxh=365,light=True)+note('梦物只能自己带着，可选“带在身上”；不能转赠、进衣柜或留到 TA 屋里。',135,1405,955,22,65,True))
add('趁醒来把梦收下','只记得一点，\n也可以先记下来。','完整的梦、只有残渣，或者没梦，都能记。\n支持语音听写时，点“懒得打字”说完再收下，醒来少打几个字。','文字 / 语音 · 完整的梦 / 残渣 / 没梦',lambda:fig('journal-voice-text','01 / 说完了，文字就留在采集框里。',120,550,940,-.7,light=True)+fig('journal-fragment','02 / 点“只有残渣”，也收得住。',150,1240,600,.7,maxh=190,light=True)+fig('journal-none','03 / 没梦也能记。',800,1240,310,-.5,maxh=190,light=True))
add('同一个梦不同解法','还是这个梦，\n换个人，换种说法。','点“找 TA 解”，挑一个人来听。\n解读会参考 TA 的人设和你们的相处；同一个梦能留多个人的解法。','选解梦人 · 多份解读并存 · 各有各的口吻',lambda:fig('journal-reading-two','这场梦里，沈屿和林夏各留了一份。',160,535,750,-.6,maxh=910,light=True)+note('完整的梦能解，\n一小段残渣\n也能交给 TA。\n\n想换个人，\n再点“找 TA 解”。',930,630,175,24,410))
add('攒一册梦签','每次解完，\nTA 再给你留一句。','梦签是 TA 写在这次解读末尾的那句话。\n在“梦签”页一起收着，能看到是谁、为哪场梦、哪天写的。','解梦后的那一句 · 梦签册 · 人与日期',lambda:fig('journal-signs-list','一句一句攒起来，再慢慢翻。',150,555,860,.7,maxh=865,light=True))
add('反复梦见什么','这扇门，\n怎么又梦见了。','“反复梦见”会把多条梦里重复出现的词整理出来。\n看出现次数和记梦天数；与这次有关的重复内容，也能成为解读参考。','出现至少 2 次 · 次数整理 · 记梦率',lambda:fig('journal-motifs','01 / 反复出现的内容，集中看。',120,565,940,-.6,light=True)+fig('journal-fragment','02 / 一点颜色和画面，也能成为记录。',150,1000,750,.7,light=True)+note('先把梦记下来，\n再看哪些东西一直回来。',150,1330,920,35,115))
add('TA昨晚的梦','TA 的白天，\n揉成 TA 的夜晚。','“TA 们的梦”取材于昨天的对话、情绪和关系状态。\n未醒的梦点一下才生成；平静或没有材料的夜，也可能只留无梦。','TA 的夜梦 · 点开成形 · 推门进入同一场梦',lambda:fig('their-dream','读这一场，也能点“推门进这场梦”。',110,555,650,-.8,maxh=660,light=True)+fig('their-queued','未醒的梦，点一下让它成形。',815,565,300,1,maxh=265,light=True)+fig('their-generated','点过以后，沿原记录留下正文。',815,860,300,-.5,maxh=390,light=True)+fig('their-nodream','那晚，也可能没有梦。',135,1260,625,.6,maxh=165,light=True))
add('碎掉的夜梦会回来','那场碎掉的梦，\nTA 又做了一次。','从 TA 的夜梦进去、半路碎掉的，隔 2—7 晚会回来一次。\n沿碎之前的进度接着走，接下来重新给选项，路会跟着近况变化。','仅 TA 夜梦 · 2—7 晚 · 每场只回来一次',lambda:fig('dream-recur-banner','01 / 这次回来，从上次碎掉的地方接。',110,540,960,-.6)+fig('dream-recur-scene','02 / 旧地方还在，这次的路已经变了。',140,825,920,.7,maxh=415)+fig('dream-recur-options','03 / 这一步重新选。',175,1260,850,-.5,maxh=210))
add('醒后聊天的余味','你走到哪里，\nTA 醒来就留多少。','读过或进入 TA 的夜梦后，今天的聊天会带一点余味。\n抵达 / 直面能自然提一句；半路碎了，只剩说不连贯的画面。','解梦馆 × 梦境 × 聊天 · 梦的余味',lambda:fig('chat-echo-tell-crop','01 / 抵达之后：醒来还记得清。',110,550,925,-.6,maxh=485,light=True)+fig('chat-echo-vague-crop','02 / 半路碎了：只剩零碎画面。',200,1060,850,.6,maxh=325,light=True)+note('只读过或自己醒来：留余味，等你提起再接。隔夜不主动重讲，余味 3 天过期；梦剧情不写进正式记忆。',120,1405,960,20,85,True))

css='''*{box-sizing:border-box}html,body{margin:0;width:1200px;height:1600px;overflow:hidden}body{background:#101b2d url('../assets/dream-night.png') center/cover;color:#eee9e3;font-family:"PingFang SC",sans-serif}.veil{position:absolute;inset:0;background:linear-gradient(90deg,#0b142150,#11182812 62%,#1117280a)}.edge{position:absolute;inset:28px;border:1px solid #c3c9d420}.brand{position:absolute;left:88px;top:66px;font-family:"Songti SC",serif;font-size:27px;line-height:42px;letter-spacing:.12em;color:#cbd1df}.brand:before{content:"";display:inline-block;width:38px;height:1px;margin:0 17px 9px 0;background:#c3b4a1}.edition{position:absolute;left:91px;top:118px;color:#a6afc0;font-size:18px;line-height:28px;letter-spacing:.09em}.stamp{position:absolute;right:78px;top:59px;width:118px;height:118px;border:1px solid #c0bdbb50;border-radius:50%;font-family:"Songti SC",serif;font-size:24px;line-height:32px;text-align:center;padding-top:24px;color:#cabda9;transform:rotate(8deg)}.stamp:before{content:"";position:absolute;inset:7px;border:1px dashed #c0bdbb30;border-radius:50%}h1{position:absolute;left:82px;top:186px;width:1050px;height:214px;margin:0;font-family:"Songti SC",serif;font-size:72px;line-height:94px;font-weight:700;letter-spacing:.025em;text-shadow:0 3px 15px #0002}.sub{position:absolute;left:91px;top:412px;width:1000px;height:100px;margin:0;font-size:25px;line-height:42px;color:#c2c6d0}.native{margin:0;padding:13px 13px 8px;position:absolute;background:#141d2b;border:1px solid #c3c9d443;box-shadow:0 20px 44px #060d1b60,0 3px 10px #0004;isolation:isolate}.native:before{content:"";position:absolute;width:62px;height:1px;background:#c3a9909c;top:-9px;left:25px}.native img{display:block;width:100%;height:auto}.native figcaption{height:41px;padding-top:10px;color:#c8c8cd;font-size:var(--cap);line-height:30px;font-family:"Songti SC",serif;white-space:nowrap}.native.light{background:#eee8de;border-color:#d4c5b188;box-shadow:0 16px 45px #040b1655,0 2px 5px #0005}.native.light figcaption{color:#62596b}.note{position:absolute;margin:0;font-family:"Songti SC",serif;color:#d3c7b7;font-weight:600;line-height:1.55}.note.small{font-family:"PingFang SC",sans-serif;color:#c1c4ce;font-weight:400;line-height:1.65}.footer{position:absolute;top:1515px;left:91px;width:1018px;border-top:1px solid #c0c7d235;padding-top:10px;text-align:center}.features{font-size:22px;line-height:29px;color:#d2c6b7}.demo{font-size:15px;line-height:23px;color:#929caf;margin-top:5px}.cover h1{font-size:79px;line-height:100px}.cover .sub{font-size:26px}'''
records=[]
for i,d in enumerate(items,1):
    used=[];body=d['build']();r={k:d[k] for k in ['name','title','sub','features']};r.update(id=i,file=f'{i:02d}-{d["name"]}.png',native=used);records.append(r)
    doc=f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>秋秋机 · 梦境与解梦馆 · {E(d["name"])}</title><style>{css}</style></head><body class="'+('cover' if i==1 else '')+f'"><div class="veil"></div><div class="edge"></div><div class="brand checked">秋秋机 · 梦境 × 解梦馆</div><div class="edition checked">{i:02d} / {E(d["name"])}</div><div class="stamp checked">夜里<br>见面</div><h1 class="checked">{E(d["title"])}</h1><p class="sub checked">{E(d["sub"])}</p>{body}<div class="footer"><div class="features checked">{E(d["features"])}</div><div class="demo checked">真实功能界面 · 人物、梦境、解读与聊天回复为虚构演示数据</div></div></body></html>'
    (p/'editable'/f'{i:02d}.html').write_text(doc)
assert len(records)==18
(p/'manifest.json').write_text(json.dumps({'title':'秋秋机 · 梦境 × 解梦馆','size':[1200,1600],'records':records},ensure_ascii=False,indent=2))
print('18 poster sources ready')
